// The identical case functions execute against the pinned real Node Buffer and
// the native WebView2 Buffer. Expected results are never generated by the facade.
module.exports = function bufferCases(B) {
  const cases = [];
  function normalize(value) {
    if (typeof value === 'bigint') return { bigint: String(value) };
    if (typeof value === 'number' && (!Number.isFinite(value) || Object.is(value, -0))) return { number: Object.is(value, -0) ? '-0' : String(value) };
    if (value === undefined) return { undefined: true };
    if (ArrayBuffer.isView(value)) return { bytes: Array.from(new Uint8Array(value.buffer, value.byteOffset, value.byteLength)), buffer: B.isBuffer(value) };
    if (Array.isArray(value)) return value.map(normalize);
    if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, normalize(item)]));
    return value;
  }
  function test(name, run) {
    try { cases.push({ name, result: normalize(run()) }); }
    catch (error) { cases.push({ name, error: { name: error.name, code: error.code || null, type: error instanceof TypeError, range: error instanceof RangeError } }); }
  }
  for(const size of [-1,0,1,1.5,NaN,Infinity,'2',null,undefined])for(const method of ['alloc','allocUnsafe','allocUnsafeSlow'])test('allocate/'+method+'/'+String(size),()=>B[method](size).fill(9));
  for(const size of [0,2,'3','x',undefined,-1,1n])test('slow/'+String(size),()=>require('buffer').SlowBuffer(size).fill(9));
  for(const start of [-Infinity,Infinity,NaN,null,true,'2',-4,1.5,100,undefined])for(const end of [undefined,-1,2,0,Infinity])test('slice/'+String(start)+'/'+String(end),()=>B.from([1,2,3,4,5]).slice(start,end));
  test('concat-many-backing-stores',()=>B.concat(Array.from({length:300},(_,index)=>new Uint8Array([index&255]))));
  test('small-view-large-backing',()=>{const backing=new ArrayBuffer(8*1024*1024),b=B.from(backing,7000000,8);b.fill(6);return [b,b.toString('hex'),new Uint8Array(backing)[7000000]];});
  for (const encoding of ['utf8','utf-8','utf16le','utf-16le','ucs2','ucs-2','hex','base64','base64url','latin1','ascii','binary']) {
    const text = ['hex','base64','base64url'].includes(encoding) ? 'abcdefff' : '\ufeff中文😀é\u0000';
    test('encoding/'+encoding,()=>{const b=B.from(text,encoding);return [b,b.toString(encoding),B.byteLength(text,encoding),B.isEncoding(encoding)];});
  }
  for (const text of ['a','ab:c','abc','abzzcd','a\n_b-==','??a','a===','😀']) for(const encoding of ['hex','base64','base64url']) test('partial/'+encoding+'/'+text,()=>B.from(text,encoding));
  for(const value of [[],[1,-1,256,1.9,NaN,null,undefined,'257'],{type:'Buffer',data:[1,2,255]},{length:3,0:1,2:255},{length:'2',0:9},{valueOf(){return '转换';}},{[Symbol.toPrimitive](){return 'primitive';}},Object.assign(Object.create({0:9}),{length:2,1:8}),new Uint16Array([0x1234,0xabcd]),new DataView(new ArrayBuffer(5))]) {
    const index=cases.length;test('from-object/'+index,()=>B.from(value));
  }
  test('from-shared-arraybuffer',()=>{const raw=new ArrayBuffer(12),all=new Uint8Array(raw);all.fill(8);const b=B.from(raw,2,4);b[1]=44;return [Array.from(all),b.byteOffset,b.length,b.buffer===raw,b.parent===raw,b.offset===b.byteOffset];});
  test('slice-and-subarray-share',()=>{const b=B.from([1,2,3,4,5,6]),slice=b.slice(1,-1),sub=b.subarray(2,4);slice[1]=90;sub[1]=80;return [b,slice,sub,B.isBuffer(slice),slice!==b,slice.buffer===b.buffer,slice.byteOffset===b.byteOffset+1];});
  test('same-range-new-view',()=>{const b=B.from([1,2]);return [b.slice()!==b,b.subarray()!==b];});
  test('copy-buffer-is-independent',()=>{const original=B.from([1,2]),copy=B.from(original);copy[0]=99;return [original,copy,copy.buffer===original.buffer&&copy.byteOffset===original.byteOffset];});
  for(const direction of ['forward','backward']) test('overlapping-copy/'+direction,()=>{const b=B.from([1,2,3,4,5,6]);const count=direction==='forward'?b.copy(b,2,0,4):b.copy(b,0,2,6);return [count,b];});
  test('overlapping-views-copy',()=>{const b=B.from([1,2,3,4,5,6]),a=b.subarray(0,4),target=b.subarray(2,6);return [a.copy(target),b];});
  test('overlapping-fill',()=>{const b=B.from([1,2,3,4,5,6]);return [b.fill(b.subarray(0,3),1)===b,b];});
  test('fill-view-and-parent',()=>{const b=B.alloc(10,1),v=b.slice(2,8);return [v.fill('ab','utf8')===v,b];});
  test('copyBytesFrom-numeric-view',()=>B.copyBytesFrom(new Uint16Array([0x1234,0xabcd,0xffee]),1,1));
  test('legacy-constructor',()=>[B([1,2]),new B([3,4]),B(3).fill(7)]);
  test('buffer-module-identity',()=>[require('buffer')===require('node:buffer'),require('buffer').Buffer===B,B.prototype.constructor===B,B.isBuffer(new Uint8Array(2))]);
  test('method-aliases',()=>[B.prototype.toLocaleString===B.prototype.toString,B.prototype.readUint32LE===B.prototype.readUInt32LE,B.prototype.writeBigUint64BE===B.prototype.writeBigUInt64BE]);
  test('method-signatures',()=>['from','alloc','isBuffer','byteLength'].map(name=>[name,B[name].name,B[name].length]).concat(['copy','readUIntLE','readFloatLE','writeBigInt64BE','subarray','slice','toJSON'].map(name=>[name,B.prototype[name].name,B.prototype[name].length])));
  test('typed-array-inheritance',()=>{const b=B.from([1,2,3]);return [ArrayBuffer.isView(b),b instanceof Uint8Array,b.map(x=>x+1),b.filter(x=>x>1),Array.from(b.values()),JSON.stringify(b)];});
  test('concat-and-compare',()=>[B.concat([B.from([1,2]),new Uint8Array([3,4])],6),B.compare(B.from([1,2]),new Uint8Array([1,3]))]);
  test('search-and-write',()=>{const b=B.alloc(16);const n=b.write('中文abc',1,'utf8');return [n,b,b.indexOf('abc'),b.includes('中文'),b.lastIndexOf(0),b.compare(B.alloc(4),0,4,0,4)];});
  for(const bits of [16,32,64])test('swap/'+bits,()=>{const b=B.from([1,2,3,4,5,6,7,8]);return [b['swap'+bits]()===b,b];});
  for(const endian of ['LE','BE']) {
    for(const [kind,width,values]of [['UInt',1,[0,255]],['UInt',2,[0,65535]],['UInt',4,[0,4294967295]],['Int',1,[-128,127]],['Int',2,[-32768,32767]],['Int',4,[-2147483648,2147483647]],['Float',4,[0,-0,1.5,-13.25,NaN,Infinity]],['Double',8,[0,-0,1.5,Math.PI,NaN,-Infinity]],['BigUInt',8,[0n,18446744073709551615n]],['BigInt',8,[-9223372036854775808n,9223372036854775807n]]]) {
      const suffix=kind==='Float'||kind==='Double'?kind+endian:kind+(width*8)+(width===1?'':endian);
      for(const value of values)test('numeric/'+suffix+'/'+String(value)+(Object.is(value,-0)?'-zero':''),()=>{const b=B.alloc(20,3);const n=b['write'+suffix](value,2);return [n,b,b['read'+suffix](2)];});
    }
    for(const width of [1,2,3,4,5,6])for(const signed of [false,true])for(const value of signed?[-1,-(2**(width*8-1)),2**(width*8-1)-1]:[0,2**(width*8)-1]) {
      const kind=signed?'Int':'UInt';test('variable/'+kind+endian+'/'+width+'/'+value,()=>{const b=B.alloc(12,6);return [b['write'+kind+endian](value,1,width),b,b['read'+kind+endian](1,width)];});
    }
  }
  for(const method of ['readUInt8','readUInt32LE','readDoubleBE','readBigInt64LE'])for(const length of [0,2,8])for(const offset of [undefined,null,-1,0.5,NaN,Infinity,'1',99])test('read-error/'+method+'/'+length+'/'+String(offset),()=>B.alloc(length)[method](offset));
  for(const value of [undefined,NaN,'12',-1,256,Infinity,1n])for(const offset of [undefined,null,-1,0.5,99])test('write-edge/'+String(value)+'/'+String(offset),()=>{const b=B.alloc(4,9);return [b.writeUInt8(value,offset),b];});
  for(const args of [[1,0],[1,-1],[1,0,7],[1,null,2],[1,0,0],[1,0,'2']])test('variable-error/'+String(args),()=>{const b=B.alloc(8);return b.writeUIntLE(...args);});
  for(const invalid of [null,undefined,4,Symbol('x'),{foo:1}]) test('invalid-from/'+String(invalid),()=>B.from(invalid));
  test('invalid-encoding',()=>B.from('text','not-an-encoding'));
  test('invalid-fill',()=>B.alloc(4).fill('x',0,4,'not-an-encoding'));
  test('invalid-copy-target',()=>B.from([1,2]).copy({length:2}));
  test('invalid-concat-item',()=>B.concat([new Uint16Array([1,2])]));
  return cases;
};
if(require.main===module)console.log(JSON.stringify(module.exports(Buffer)));
